INSERT INTO `document_templates` (`id`, `name`, `description`, `content`, `page_size`, `orientation`, `is_active`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Barangay Clearance', NULL, '<p><strong>TO&nbsp;WHOM&nbsp;THIS&nbsp;MAY&nbsp;CONCERN:</strong></p><p></p><p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;This&nbsp;is&nbsp;to&nbsp;certify&nbsp;that&nbsp;the&nbsp;business&nbsp;or&nbsp;trade&nbsp;activity&nbsp;described&nbsp;below:</p><p></p><p class=\"ql-align-center\"><strong><u>{{&nbsp;fields.business_name&nbsp;}}</u></strong></p><p class=\"ql-align-center\">(Business&nbsp;Name&nbsp;or&nbsp;Trade&nbsp;Activity)</p><p class=\"ql-align-center\"></p><p class=\"ql-align-center\"><strong><u>{{&nbsp;fields.location&nbsp;}}</u></strong></p><p class=\"ql-align-center\">(Location)</p><p class=\"ql-align-center\"></p><p class=\"ql-align-center\"><strong><u>{{&nbsp;fields.operation_manager&nbsp;}}</u></strong></p><p class=\"ql-align-center\">(Operator/Manager)</p><p class=\"ql-align-center\"></p><p class=\"ql-align-center\"><strong><u>{{&nbsp;resident.address&nbsp;}}</u></strong></p><p class=\"ql-align-center\">(Address)</p><p class=\"ql-align-center\"></p><p class=\"ql-align-justify\">Propose&nbsp;to&nbsp;be&nbsp;established&nbsp;in&nbsp;this&nbsp;Barangay&nbsp;and&nbsp;is&nbsp;being&nbsp;applied&nbsp;for&nbsp;a&nbsp;Barangay&nbsp;Clearance&nbsp;to&nbsp;be&nbsp;used&nbsp;in&nbsp;securing&nbsp;a&nbsp;corresponding&nbsp;Barangay&nbsp;Permit&nbsp;has&nbsp;been&nbsp;found&nbsp;to&nbsp;be:</p><p class=\"ql-align-justify\"></p><p class=\"ql-align-justify\">___/&nbsp;In&nbsp;conformity&nbsp;with&nbsp;the&nbsp;provision&nbsp;of&nbsp;existing&nbsp;Barangay&nbsp;Ordinances,&nbsp;rules&nbsp;and&nbsp;&nbsp;&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;regulations&nbsp;being&nbsp;enforced&nbsp;in&nbsp;this&nbsp;barangay;</p><p class=\"ql-align-justify\"></p><p class=\"ql-align-justify\">___/Not&nbsp;among&nbsp;those&nbsp;businesses&nbsp;or&nbsp;trade&nbsp;activities&nbsp;being&nbsp;banned&nbsp;to&nbsp;be&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;established&nbsp;in&nbsp;this&nbsp;barangay;</p><p class=\"ql-align-justify\"></p><p class=\"ql-align-justify\">In&nbsp;view&nbsp;of&nbsp;the&nbsp;foregoing,&nbsp;this&nbsp;barangay,&nbsp;thru&nbsp;the&nbsp;undersigned.</p><p class=\"ql-align-justify\"></p><p class=\"ql-align-justify\">___/&nbsp;Interposes&nbsp;no&nbsp;objection&nbsp;for&nbsp;the&nbsp;issuance&nbsp;of&nbsp;the&nbsp;corresponding&nbsp;Barangay&nbsp;</p><p class=\"ql-align-justify\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Permit&nbsp;being&nbsp;applied&nbsp;for.</p><p class=\"ql-align-justify\"></p><p class=\"ql-align-justify\">Issued&nbsp;this&nbsp;9<sup>TH</sup>&nbsp;day&nbsp;of&nbsp;<strong><u>December,&nbsp;2025&nbsp;</u></strong>at&nbsp;Barangay&nbsp;Duyay,&nbsp;Boac,&nbsp;Marinduque.</p>', 'A4', 'portrait', 1, '2026-09-20 23:28:24', '2026-09-22 02:09:24', NULL),
(2, 'Certificate of Indigency', NULL, '<p class=\"ql-align-justify\"><strong>TO&nbsp;WHOM&nbsp;IT&nbsp;MAY&nbsp;CONCERN:</strong></p><p class=\"ql-align-justify\"></p><p class=\"ql-align-justify\">	This&nbsp;is&nbsp;to&nbsp;certify&nbsp;that&nbsp;<u>{{&nbsp;resident.full_name&nbsp;}}</u>,&nbsp;<u>{{&nbsp;resident.age&nbsp;}}</u>&nbsp;years&nbsp;age,&nbsp;Filipino,&nbsp;and&nbsp;presently&nbsp;residing&nbsp;at&nbsp;Barangay&nbsp;{{&nbsp;barangay.name&nbsp;}},&nbsp;Boac,&nbsp;Marinduque&nbsp;belongs&nbsp;to&nbsp;indigent&nbsp;family&nbsp;in&nbsp;this&nbsp;Barangay.</p><p class=\"ql-align-justify\"></p><p class=\"ql-align-justify\">	This&nbsp;certification&nbsp;is&nbsp;being&nbsp;issued&nbsp;upon&nbsp;the&nbsp;request&nbsp;of&nbsp;the&nbsp;above&nbsp;persons&nbsp;for&nbsp;<u>{{&nbsp;request.purpose&nbsp;}}</u>.</p><p class=\"ql-align-justify\">	</p><p class=\"ql-align-justify\">	Issued&nbsp;this&nbsp;<u>{{&nbsp;request.signed_at&nbsp;}}</u>&nbsp;at&nbsp;Barangay&nbsp;{{&nbsp;barangay.name&nbsp;}},&nbsp;Boac,&nbsp;Marinduque.</p><p></p>', 'A4', 'portrait', 1, '2026-11-02 01:18:33', '2026-11-02 01:18:33', NULL);
